function repeatedSubstringPattern(s) {
  const n = s.length;
  const lps = new Array(n).fill(0);
  let length = 0;
  for (let i = 1; i < n; i++) {
    while (length > 0 && s[i] !== s[length]) {
      length = lps[length - 1];
    }
    if (s[i] === s[length]) {
      length++;
    }
    lps[i] = length;
  }
  const border = lps[n - 1];
  const period = n - border;
  return border > 0 && n % period === 0;
}

