function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const letters = 'abcdefghijklmnopqrstuvwxyz'.slice(0, 1 + pick(large ? 4 : 3));
  const randomText = length => Array.from({ length }, () => letters[pick(letters.length)]).join('');
  const style = pick(3);
  if (style === 0) {
    // Plain random text: usually not a repetition.
    return [randomText(large ? 9000 + pick(1001) : 1 + pick(12))];
  }
  // A block repeated; style 2 then changes one character so the repetition may break.
  const unit = randomText(large ? 1 + pick(50) : 1 + pick(4));
  const copies = large ? Math.floor((9000 + pick(1000)) / unit.length) : 1 + pick(4);
  let s = unit.repeat(copies);
  if (style === 2) {
    const at = pick(s.length);
    s = s.slice(0, at) + letters[pick(letters.length)] + s.slice(at + 1);
  }
  return [s];
}
